import{_ as l,l as r,o as e,c as s,v as t,p as o,x as i,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"计划提示与稳定性","description":"","frontmatter":{"title":"计划提示与稳定性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/plan-hints-stability.md","filePath":"cs/plan-hints-stability.md","lastUpdated":1789023840000}'),E={name:"cs/plan-hints-stability.md"};function c(_,a,A,m,u,B){const n=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="计划提示与稳定性" tabindex="-1">计划提示与稳定性 <a class="header-anchor" href="#计划提示与稳定性" aria-label="Permalink to &quot;计划提示与稳定性&quot;">​</a></h1><div class="epigraph"><p>提示把搜索剪成一条指定路径；稳定性要求同一语句在统计微扰下不要突然换树。两者都是对优化器自主性的约束，不是代数律。</p><footer>—— 据 Weikum 等对计划稳定性；产品优化器 hint 文档；Selinger 搜索对照</footer></div><p><a href="/cs/mv-refresh">上一课</a>把物化当可匹配的副本。本课不写 delta 规则。缺口是运维：学习估计、缓存、自动 ANALYZE 会让计划在版本之间跳动。提示（hint）强制访问路径或连接顺序；稳定性（plan stability / baselines）把验收过的计划钉住。优化器单元接近收口，回归下一课专门命名「变慢」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DP 每次可合法地选出不同树：统计刷新、参数窥视、软件版本。报表昨日 2 秒、今日 200 秒，指称仍对。缺口是<strong>控制权</strong>：hint 嵌入 SQL 或大纲（outline）存服务器。过强的 hint 在索引删除后变成错误或静默忽略——合同必须写清。</p><p>稳定性不是最优：钉住的计划在数据长大后可能变差。它换的是可预测。与自适应相反：自适应要变，稳定性不要变。工作负载要分类：OLTP 短查询常要稳定；一次性分析可全搜索。</p><p><span class="marginnote">Oracle SQL Plan Baseline、SQL Server 计划指南一类是产品名。本课要的机制：存储一套可接受计划，优化器只在代价显著更好且通过验证时才换。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>hint：指定索引名、连接算法、顺序、禁止某种改写。范围尽量小，避免整句写死。baseline：第一次好计划入库；演化时候选计划在影子执行或代价阈值下晋升。失败回退上次。</p><p>与预编译：通用计划本身就是一种稳定性（不看参数）。倾斜时要允许特殊计划例外列表，而不是全局关缓存。</p>',10)),(e(),o(d,null,{default:i(()=>[p(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRCH%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E6%90%9C%E7%B4%A2%22%5D%20--%3E%20HINT%5B%22%E6%8F%90%E7%A4%BA%E5%89%AA%E6%9E%9D%22%5D%0A%20%20SRCH%20--%3E%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E8%AE%A1%E5%88%92%22%5D%0A%20%20BASE%20--%3E%20EVOL%5B%22%E5%80%99%E9%80%89%E6%9B%B4%E5%A5%BD%E5%88%99%E9%AA%8C%E8%AF%81%22%5D%0A%20%20EVOL%20--%3E%20PIN%5B%22%E4%BB%8D%E9%92%89%E4%BD%8F%E6%88%96%E6%99%8B%E5%8D%87%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>合法性：hint 不能打破外连接方向、不能跳过必做谓词。代价模型仍运行，只是可行集变小。日志：记录为何没用 hint（索引名改了），否则静默全扫。</p><p>提示与 ORM：生成 SQL 带 hint 使迁移脆弱。更好的是服务器侧 baseline 按语句指纹匹配。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把一次变慢的取证写完——下一课计划回归。也不把 hint 当索引选择的替代：缺索引应建索引，而不是 hint 一个不存在的名字。</p><p>后课默认：生产关键语句可钉计划；钉住要有过期审查。回归课用估计/实际与变更事件解释「为何换树」。</p><p>稳定性是运维不变式，不是查询指称的一部分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>提示缩小搜索；基线把验收计划钉住并可受控演化。</li><li>索引消失后 hint 必须失败可见。</li><li>计划回归下一课：把「突然变慢」收成诊断对象。</li><li>出处：计划稳定性实践；Selinger 对照；Ramakrishnan and Gehrke。</li></ul>',9))])}const f=l(E,[["render",c]]);export{b as __pageData,f as default};
